package com.bank.benefits;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class BenefitsDemo {
    private static final Logger log = Logger.getLogger("Benefits");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", new BigDecimal("95000")),
            new Employee(2L, "Priya", new BigDecimal("250000")),
            new Employee(3L, "Amit", new BigDecimal("45000")),
            new Employee(4L, "Sneha", new BigDecimal("50000"))
        );
        BenefitsService service = new BenefitsService();
        Map<Boolean, List<Employee>> parts = service.partitionBySalary(staff);
        log.info(() -> "Above 50k: " + parts.get(true).stream().map(Employee::getName).toList());
        log.info(() -> "50k or below: " + parts.get(false).stream().map(Employee::getName).toList());

        Map<Boolean, Long> counts = service.countBySalaryBand(staff);
        log.info(() -> "Counts (true=above): " + counts);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final BigDecimal salary;
    Employee(Long id, String name, BigDecimal salary) { this.id = id; this.name = name; this.salary = salary; }
    String getName() { return name; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/BenefitsService.java ───
class BenefitsService {
    private static final BigDecimal THRESHOLD = new BigDecimal("50000");

    // partitioningBy: exactly two keys (true/false), both ALWAYS present.
    Map<Boolean, List<Employee>> partitionBySalary(List<Employee> employees) {
        return employees.stream()
            .collect(partitioningBy(e -> e.getSalary().compareTo(THRESHOLD) > 0));
    }

    // partitioningBy with counting() downstream → Map<Boolean, Long>.
    Map<Boolean, Long> countBySalaryBand(List<Employee> employees) {
        return employees.stream()
            .collect(partitioningBy(e -> e.getSalary().compareTo(THRESHOLD) > 0, counting()));
    }
}
